	@Test
	void fallsBackToExactEncodedKeySortingWhenTupleOrderIsNotAdvertised() throws Exception {
		var valueFactory = SimpleValueFactory.getInstance();
		IRI predicate = valueFactory.createIRI("urn:predicate");
		Statement statement = valueFactory.createStatement(valueFactory.createIRI("urn:subject"), predicate,
				valueFactory.createIRI("urn:object"));
		LmdbStoreConfig config = new LmdbStoreConfig("spoc");
		Path staging = Files.createDirectory(temporaryDirectory.resolve("encoded-staging"));
		CanonicalStagedInput staged;
		try (CanonicalStatementStager stager = new CanonicalStatementStager(staging, config, 4, 4, 64 * 1024L,
				BulkCompression.FASTEST)) {
			stager.writeStatement(statement);
			staged = stager.stagedInput();
		}
		ValueDependencyBuckets dependencies = ValueDependencyCollector.collect(staged, staging, 4, 4, config,
				BulkCompression.FASTEST, () -> false);
		PartitionValueDictionary dictionary = PartitionValueDictionaryBuilder.build(staged, dependencies, staging, 4,
				64 * 1024L, 4, config, BulkCompression.FASTEST, () -> false);
		ResolvedIdQuadSpool spool = ResolvedIdQuadSpool.build(staged, dictionary, staging, 4, 64 * 1024L,
				BulkCompression.FASTEST, () -> false);

		List<ValueStore.BulkRecord> encoded = new ArrayList<>();
		try (StatementIndexBulkRecords records = StatementIndexBulkRecords.build(spool, staging, "spoc", 128L, 4,
				BulkCompression.FASTEST,
				(BooleanSupplier) () -> false, (Predicate<String>) ignored -> false)) {
			StatementIndexBulkRecords.IndexRun run = records.runs().getFirst();
			assertThat(run.encodedRecords()).isNotNull();
			assertThat(run.tuples()).isNull();
			run.encodedRecords().forEach((key, value) -> encoded.add(new ValueStore.BulkRecord(key, value)));
		}

		Path generation = temporaryDirectory.resolve("encoded-generation");
		try (LmdbNativeBulkStore store = new LmdbNativeBulkStore(generation, config)) {
			var iterator = encoded.iterator();
			assertThat(store.appendExplicitEncodedIndex("spoc",
					() -> iterator.hasNext() ? iterator.next() : null, 1, Long.MAX_VALUE))
							.isEqualTo(1L);
		}
	}

	private static List<String> read(StatementIndexBulkRecords.IndexRun run) throws Exception {
		List<String> tuples = new ArrayList<>();
		run.tuples().forEach(tuple -> tuples.add(Arrays.toString(tuple)));
		return tuples;
	}

	private static long[] quad(PartitionValueDictionary dictionary, Statement statement) throws Exception {
		return new long[] {
				lookup(dictionary, CanonicalTermCodec.encode(statement.getSubject())),
				lookup(dictionary, CanonicalTermCodec.encode(statement.getPredicate())),
				lookup(dictionary, CanonicalTermCodec.encode(statement.getObject())),
				statement.getContext() == null ? 0L
						: lookup(dictionary, CanonicalTermCodec.encode(statement.getContext()))
		};
	}

	private static long[] ordered(long[] quad, String specification) {
		long[] ordered = new long[4];
		for (int i = 0; i < ordered.length; i++) {
			ordered[i] = quad[switch (specification.charAt(i)) {
			case 's' -> 0;
			case 'p' -> 1;
			case 'o' -> 2;
			case 'c' -> 3;
			default -> throw new IllegalArgumentException(specification);
			}];
		}
		return ordered;
	}

	private static List<String> sorted(String specification, long[]... quads) {
		List<String> result = Arrays.stream(quads)
				.map(quad -> ordered(quad, specification))
				.sorted(Arrays::compareUnsigned)
				.map(Arrays::toString)
				.toList();
		return result;
	}

	private static long lookup(PartitionValueDictionary dictionary, byte[] key) throws Exception {
		int partition = (int) CanonicalTermCodec.routeHash64(key) & 3;
		try (PartitionValueDictionary.PartitionReader reader = dictionary.openPartition(partition)) {
			long id = reader.lookup(key);
			assertThat(id).isNotZero();
			return id;
		}
	}
